def transform(grid):
    out = [row[:] for row in grid]
    if not grid:
        return out
    w = len(grid[0])
    bars = [r for r, row in enumerate(grid) if len(row) == w and all(v == 2 for v in row)]
    if not bars:
        return out
    bar = bars[0]
    top, bottom = grid[0], grid[-1]
    shared = [c for c in range(w) if top[c] != 0 and top[c] == bottom[c]]
    for c in shared:
        color = top[c] + 1
        for r in range(1, bar):
            if out[r][c] == 0:
                out[r][c] = color
    return out
